mkdir -p /app/output /app/runs && cat > /app/output/gen.py <<'PY'
import os, sys, json, time, traceback
sys.path.insert(0, '/opt/tools')
import numpy as np
from PIL import Image
from scipy.spatial.transform import Rotation as R
from rcb_client import Robot, EpisodeOver
r = Robot()
spec = r.spec()
open('/app/output/spec.json','w').write(json.dumps(spec,indent=2))
idx=0
obs=None

def record(res):
    global idx, obs
    obs=res
    path=f'/app/runs/{idx:03d}'
    res.save(path)
    for c,im in res.last.items():
        short='head' if 'zed' in c else ('left' if 'left' in c else 'right')
        Image.fromarray(im).resize((672,672)).save(f'/app/output/{short}.png')
    print('RESULT',idx,json.dumps({k:v for k,v in res.meta.items() if k not in ['cameras','proprio']},default=str),flush=True)
    idx+=1
    return res

def observe(): return record(r.get_obs(depth=True))
def now(): return dict(zip(obs.meta['proprio']['layout'],obs.meta['proprio']['now']))
def pose(side='left',tcp=False):
    return obs.group(side+('_tcp_pose' if tcp else '_eef_pose'),now=True)
def joints():
    p=now(); return np.array([p[n] for n in spec['kinematics']['joint_names']])
def act(a,dt=0.1,**kw): return record(r.submit('joint_position',a,dt=dt,depth=True,**kw))
def ee(l=None,rr=None,lg=1,rg=1):
    l=pose('left') if l is None else np.array(l); rr=pose('right') if rr is None else np.array(rr)
    return record(r.submit('ee_pose',np.r_[l,lg,rr,rg],depth=True))
def point(cam,u,v):
    c=next(k for k in obs.last if cam in k)
    d=float(obs.last_depth[c][v,u]); cal=obs.meta['cameras'][c]
    K=np.array(cal['intrinsic_cv']); E=np.array(cal['extrinsic_cv']);
    pc=np.linalg.solve(K,np.array([u,v,1.]))*d
    return E[:,:3].T@(pc-E[:,3])
print('READY',flush=True)
observe()
for line in sys.stdin:
    try:
        cmd=json.loads(line)['code']
        with open('/app/output/commands.jsonl','a') as f:f.write(json.dumps({'code':cmd})+'\n')
        exec(compile(cmd,'<robot-command>','exec'),globals())
    except Exception:
        traceback.print_exc()
    print('COMMAND_DONE',flush=True)
PY
python -u /app/output/gen.py

